401,4402,4403,4404,4405,4406,4407,4408,4409,4410,4411\"]</p>\r\n<!-- /wp:image -->', 'Жилые комплексы', '', 'inherit', 'closed', 'closed', '', '4264-revision-v1', '', '', '2019-06-28 16:02:09', '2019-06-28 13:02:09', '', 4264, 'http://nedvizhimost-v-turcii.com/4264-revision-v1/', 0, 'revision', '', 0),
