1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/kizlar-pinari/\"][yaplacemark  name=\"Район Saray\" coord=\"36.5546, 31.9876\" icon=\"islands#dotIcon\" color=\"#1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/Saray/\"][yaplacemark  name=\"Район Tepe\" coord=\"36.5682,31.9910\" icon=\"islands#dotIcon\" color=\"#1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/Tepe/\"][yaplacemark  name=\"Район Hisarici\" coord=\"36.5317,31.9922\" icon=\"islands#dotIcon\" color=\"#1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/hisarici/\"][yaplacemark  name=\"Район Bektas\" coord=\"36.5655,32.0071\" icon=\"islands#dotIcon\" color=\"#1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/Bektas/\"][yaplacemark  name=\"Район Cumhuriyet\" coord=\"36.5405,32.0272\" icon=\"islands#dotIcon\" color=\"#1e98ff\" url=\"http://nedvizhimost-v-turcii.com/product-category/cumhuriyet/\"][/yamap]', 'Главная', '', 'inherit', 'closed', 'closed', '', '4333-revision-v1', '', '', '2019-04-05 18:19:51', '2019-04-05 15:19:51', '', 4333, 'http://nedvizhimost-v-turcii.com/2019/04/05/4333-revision-v1/', 0, 'revision', '', 0),
